import {GitHubAvatar} from '@github-ui/github-avatar'
import {Link} from '@primer/react'
import {useGetHovercardAttributesForType} from '@github-ui/hovercards/use-get-hovercard-attributes-for-type'
import type {User} from '@github-ui/user-selector'

export function User({user}: {user: User}) {
  const getHovercardAttributesForType = useGetHovercardAttributesForType()

  return (
    <Link
      inline
      aria-label={`View ${user.login} profile`}
      href={user.path}
      className="color-fg-default text-emphasized d-flex flex-items-center"
      {...getHovercardAttributesForType('user', {login: user.login})}
    >
      <GitHubAvatar
        className="mr-1 cursor-pointer"
        size={16}
        src={user.primaryAvatarUrl}
        square={user.path.startsWith('/apps/')}
      />
      <span>{user.login}</span>
    </Link>
  )
}

export function HoverCardUser({user}: {user: User}) {
  const getHovercardAttributesForType = useGetHovercardAttributesForType()

  return (
    <Link
      inline
      aria-label={`View ${user.login} profile`}
      href={user.path}
      className="fgColor-muted"
      {...getHovercardAttributesForType('user', {login: user.login})}
    >
      {user.login}
    </Link>
  )
}
