import {ActorFilterProvider} from '@github-ui/repos-rules/insights/providers/actor-filter-provider'
import {singleValueFilterTypes} from '@github-ui/repos-rules/shared-filter-types'
import type {User as BypassUser} from '@github-ui/user-selector'

export class RequesterFilterProvider extends ActorFilterProvider {
  constructor(actors: BypassUser[] = []) {
    super(
      {
        displayName: 'Requester',
        key: 'requester',
        description: 'Specify the requester',
        actors,
      },
      {filterTypes: singleValueFilterTypes},
    )
  }
}
